"""File eligibility filtering.

Decides which discovered paths are eligible for indexing and classifies them
by language. Policies covered here (PLAN.md §7.3, §19):

- directory exclusions/inclusions (configurable),
- maximum file size,
- binary-file detection,
- generated-file detection,
- language classification by file extension.
"""

from pathlib import Path

from cii.core.configuration import LanguageSettings, ScanSettings
from cii.core.enums import Language

_BINARY_SNIFF_BYTES = 8192

_GENERATED_MARKERS = (
    "@generated",
    "generated by",
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "do not edit",
)

_GENERATED_SNIFF_LINES = 10


class FileFilter:
    """Eligibility decisions for one project configuration."""

    def __init__(self, scan: ScanSettings, languages: LanguageSettings) -> None:
        self._scan = scan
        self._languages = languages

    def is_excluded_directory(self, relative_dir: str) -> bool:
        """Return True when a directory is excluded (component-name matching).

        A directory named in ``included_directories`` overrides the exclusion,
        including for its subtree (every path component is checked).
        """
        components = [part for part in relative_dir.replace("\\", "/").split("/") if part]
        included = set(self._scan.included_directories)
        excluded = set(self._scan.excluded_directories)
        for component in components:
            if component in included:
                return False
            if component in excluded:
                return True
        return False

    def classify(self, path: Path) -> Language | None:
        """Classify a file by exact file name first, then by extension.

        Both are case-insensitive; None means the file is unsupported.
        """
        by_name = self._languages.filenames.get(path.name)
        if by_name is not None:
            return Language(by_name)
        language = self._languages.extensions.get(path.suffix.lower())
        return Language(language) if language is not None else None

    def is_too_large(self, file_size: int) -> bool:
        return file_size > self._scan.max_file_size_bytes

    def is_binary(self, path: Path) -> bool:
        """Binary detection: a NUL byte in the first chunk marks a binary file."""
        with path.open("rb") as handle:
            chunk = handle.read(_BINARY_SNIFF_BYTES)
        return b"\x00" in chunk

    def is_generated(self, path: Path) -> bool:
        """Conservative generated-file detection on the file head.

        Only applies when ``scan.detect_generated_files`` is enabled.
        """
        if not self._scan.detect_generated_files:
            return False
        try:
            with path.open("r", encoding="utf-8", errors="ignore") as handle:
                head = "".join(handle.readline() for _ in range(_GENERATED_SNIFF_LINES))
        except OSError:
            return False
        lowered = head.lower()
        return any(marker in lowered for marker in _GENERATED_MARKERS)
